query StatsList {
  stats {
    totalUsers
    totalPublishedDatasets
    totalPublishers
    totalPublishedUsecases
    totalOrganizations
  }
}

query TopUseCases($filters: UseCaseFilter, $pagination: OffsetPaginationInput) {
  publishedUseCases(filters: $filters, pagination: $pagination) {
    id
    title
    summary
    slug
    datasetCount
    isIndividualUsecase
    user {
      fullName
      profilePicture {
        url
      }
    }
    organization {
      name
      logo {
        url
      }
    }
    logo {
      path
    }
    geographies {
      id
      name
      code
    }
    metadata {
      metadataItem {
        id
        label
        dataType
      }
      id
      value
    }
    publishers {
      logo {
        path
      }
      name
    }
    sectors {
      id
      name
    }
    created
    modified
    website
    contactEmail
  }
}

