query PublishersList {
  getPublishers {
    __typename
    ... on TypeOrganization {
      name
      id
      description
      logo {
        url
      }
      membersCount
      publishedUseCasesCount
      publishedDatasetsCount
    }
    ... on TypeUser {
      fullName
      id
      bio
      profilePicture {
        url
      }
      publishedUseCasesCount
      publishedDatasetsCount
    }
  }
}

query ChartDetailsQuery($datasetId: UUID!) {
  getChartData(datasetId: $datasetId) {
    __typename
    ... on TypeResourceChart {
      chartType
      description
      id
      name
      chart {
        options
      }
    }
    ... on TypeResourceChartImage {
      name
      id
      description
      image {
        name
        path
        url
      }
    }
  }
}

query datasetResources($datasetId: UUID!) {
  datasetResources(datasetId: $datasetId) {
    id
    created
    modified
    type
    name
    description
    previewData {
      columns
      rows
    }
    noOfEntries
    previewEnabled
    schema {
      fieldName
      id
      format
      description
    }
    fileDetails {
      format
      size
    }
  }
}

query getSimilarDataset($datasetId: UUID!) {
  getDataset(datasetId: $datasetId) {
    id
    title
    similarDatasets {
      downloadCount
      id
      title
      tags {
        id
        value
      }
      description
      created
      modified
      isIndividualDataset
      user {
        fullName
        id
        profilePicture {
          url
        }
      }
      metadata {
        metadataItem {
          id
          label
          dataType
        }
        value
      }
      geographies {
        name
      }
      license
      resources {
        id
        created
        modified
        type
        name
        description
      }
      organization {
        name
        logo {
          url
        }
        slug
        id
      }
      sectors {
        name
      }
      formats
    }
  }
}

